def type_str(self, short=False):
        """
        Returns the type of the attribute as string.

        :return: the type
        :rtype: str
        """
        if self.is_list:
            if short:
                return 'list'
            else:
                return 'list of %s' % self.type_str(short=True)
        elif self.is_dict:
            if short:
                return 'dict'
            else:
                return 'dict of %s' % self.type_str(short=True)
        else:
            return self.type.__name__

